import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static boolean isVowel(int c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int end = buf.length;
        if (end > 0 && buf[end - 1] == '\n') end--;
        int nl = 0;
        while (nl < end && buf[nl] != '\n') nl++;
        long n = Long.parseLong(new String(buf, 0, nl).trim());
        int start = Math.min(nl + 1, end);
        byte[] out = new byte[end - start + 1];
        long count = 0;
        for (int i = start; i < end; i++) {
            int ch = buf[i];
            int lower = Character.toLowerCase(ch);
            if (lower >= 'a' && lower <= 'z' && !isVowel(lower) && ++count % n == 0) {
                // Next letter in the alphabet that is not a vowel, wrapping z -> b.
                int value = (lower - 'a' + 1) % 26;
                while (isVowel('a' + value)) value = (value + 1) % 26;
                int changed = 'a' + value;
                ch = Character.isUpperCase(ch) ? Character.toUpperCase(changed) : changed;
            }
            out[i - start] = (byte) ch;
        }
        out[out.length - 1] = '\n';
        System.out.write(out);
        System.out.flush();
    }
}

package main

import (
	"io"
	"os"
	"bytes"
	"strconv"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func isVowel(c byte) bool {
	return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	data = bytes.TrimSuffix(data, []byte("\n"))
	first, message, _ := bytes.Cut(data, []byte("\n"))
	n, _ := strconv.ParseInt(strings.TrimSpace(string(first)), 10, 64)
	out := make([]byte, len(message)+1)
	var count int64
	for i, ch := range message {
		lower := ch
		if ch >= 'A' && ch <= 'Z' {
			lower = ch + 32
		}
		if lower >= 'a' && lower <= 'z' && !isVowel(lower) {
			count++
			if count%n == 0 {
				// Next letter in the alphabet that is not a vowel, wrapping z -> b.
				value := (lower - 'a' + 1) % 26
				for isVowel('a' + value) {
					value = (value + 1) % 26
				}
				changed := 'a' + value
				if ch >= 'A' && ch <= 'Z' {
					changed -= 32
				}
				ch = changed
			}
		}
		out[i] = ch
	}
	out[len(message)] = '\n'
	os.Stdout.Write(out)
}
